  assert.equal(r.ok, true);
  assert.equal(r.value.lines[1].discountPercent, 0);
});

test('addLine returns DISCOUNT_INVALID for invalid discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', name: 'Development (hour)', qty: 2, unitPrice: 9500, vatRate: 21, discountPercent: 0 }],
  };
  assert.deepEqual(addLine(invoice, { sku: 'LOGO-PACK', qty: 1, discountPercent: 150 }), { ok: false, error: 'DISCOUNT_INVALID' });
});

test('addLine updates discountPercent when adding to existing SKU', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', name: 'Development (hour)', qty: 2, unitPrice: 9500, vatRate: 21, discountPercent: 5 }],
  };
  const r = addLine(invoice, { sku: 'DEV-HOUR', qty: 3, discountPercent: 20 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].qty, 5);
  assert.equal(r.value.lines[0].discountPercent, 20);
});

test('invoiceTotals clamps total to 0 when discount exceeds subtotal', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', name: 'Development (hour)', qty: 1, unitPrice: 100, vatRate: 21, discountPercent: 100 }],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 100);
  assert.equal(totals.discount, 100);
  assert.equal(totals.total, 0);
});

